llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Diphenhydramine, a close diphenylmethyl tertiary-amine analogue, has absolute oral bioavailability of 69% in humans, with other records ranging from 42% to 72%, all above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Trimipramine, a lipophilic basic tricyclic amine, has mean absolute oral bioavailability of 41.4%, supporting adequate systemic exposure for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Meperidine, a lipophilic tertiary amine with significant first-pass metabolism, has oral bioavailability of about 52%, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Dapoxetine, a chiral tertiary amine with multiple aromatic groups, has absolute oral bioavailability of 42%, supporting high F for the query's lipophilic basic amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Milnacipran, an amide-containing drug, has absolute oral bioavailability of 85 ± 3% in humans, indicating that amide functionality does not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Ciramadol, which contains both a basic amine and a hydroxyl group, has oral bioavailability of 80 ± 7%, supporting high F for the query's basic pyrrolidinol motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Fenspiride, a nitrogen-containing heterocycle with a hydroxyl-bearing saturated ring, has absolute oral bioavailability of 90%, supporting high F for the query's azacyclic alcohol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Perindoprilat after oral perindopril had F = 19 ± 7% in young healthy subjects, just below the 20% threshold; however, this reflects prodrug conversion to a polar diacid metabolite and is structurally remote from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic tertiary amide with a basic pyrrolidinol and multiple phenyl groups. High-transfer human absolute-bioavailability analogues consistently show F > 20%, mostly 40–90%, and the only sub-20% record is mechanistically tied to prodrug/polar-acid pharmacokinetics not applicable to the query. Therefore F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No human pharmacokinetic data are available for the specific amide/pyrrolidinol scaffold.",
    "Potential P-glycoprotein efflux or extensive first-pass metabolism of the query was not directly assessed.",
    "Most analogues are smaller or have different ionizable groups, limiting exact structural transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

